import {escapeHTML as esc} from './component-markings.mjs';
import {studyBlocks} from './study-plan-content.mjs';
import {resolveLesson} from './study-plan.mjs';
import {circuits} from './circuit-library.mjs';
export function searchLaboratory(boards,query){const norm=s=>String(s).normalize('NFD').replace(/[\u0300-\u036f]/g,'').toLowerCase(),q=norm(query.trim());const entries=[...boards.map(b=>({kind:'board',id:b.id,title:b.title,label:'Placa 3D',detail:`${b.elements.length} componentes`})),...studyBlocks.flatMap(b=>b.lessons.map(id=>({kind:'lesson',id,title:resolveLesson(id)?.title||id,label:'Lección',detail:b.title}))),...(q.length>=2?boards.flatMap(b=>b.elements.map(e=>({kind:'component',id:b.id+'::'+e.name,title:e.name+' · '+(e.value||e.package),label:'Componente',detail:b.title}))):[]),...circuits.map(c=>({kind:'circuit',id:c.id,title:c.name,label:'Circuito',detail:c.group}))];return entries.filter(e=>!q||norm(e.title+' '+e.detail).includes(q)).slice(0,35);}
export function makeBackup(storage){const values={};for(let i=0;i<(storage.length||0);i++){const key=storage.key(i);if(key?.startsWith('circuitlab-'))values[key]=storage.getItem(key);}return {format:'circuitlab-backup',version:1,created:new Date().toISOString(),values};}
export function restoreBackup(storage,data){if(data?.format!=='circuitlab-backup'||data.version!==1||!data.values||typeof data.values!=='object'||Array.isArray(data.values))throw Error('La copia no es de CircuitLab.');const entries=Object.entries(data.values);if(entries.length>500||entries.some(([k,v])=>!k.startsWith('circuitlab-')||typeof v!=='string'||v.length>3e6))throw Error('Copia inválida o demasiado grande.');const previous=entries.map(([k])=>[k,storage.getItem(k)]);try{for(const [k,v]of entries)storage.setItem(k,v);}catch(e){for(const [k,v]of previous){if(v===null)storage.removeItem(k);else storage.setItem(k,v);}throw Error('No hay espacio suficiente; se ha intentado recuperar el estado anterior.');}return entries.length;}
export function mountLabPlatform(api){
 document.body.classList.add('labPlatform');const $=id=>document.getElementById(id);
 const nav=document.querySelector('.academyNav');const side=document.createElement('div');side.className='platformSidebar';side.innerHTML='<span class="sidebarKicker">ESPACIO DE TRABAJO</span>';nav.before(side);side.append(nav);const foot=document.createElement('p');foot.className='sidebarFoot';foot.innerHTML='CIRCUITLAB STUDIO<br><small>Aprender · Explorar · Comprobar</small>';side.append(foot);
 const toolbar=document.createElement('div');toolbar.className='platformToolbar';toolbar.innerHTML='<button id="globalSearch">Buscar en el laboratorio <kbd>Ctrl K</kbd></button><button id="backupOpen">Copias de seguridad</button>';document.querySelector('.studioContext').append(toolbar);
 const inspector=document.createElement('aside');inspector.className='platformInspector';inspector.innerHTML='<div class="inspectorTitle"><span>INSPECTOR</span><small>CONTEXTO DE LA PLACA</small></div><div class="inspectorTabs" role="tablist"><button role="tab" data-inspector="component" aria-selected="true">Componente</button><button role="tab" data-inspector="notes" aria-selected="false">Cuaderno</button><button role="tab" data-inspector="meter" aria-selected="false">Medir</button></div><div id="inspectorComponent" role="tabpanel"></div><div id="inspectorNotes" role="tabpanel" hidden></div><div id="inspectorMeter" role="tabpanel" hidden></div>';
 const workspace=$('labPage').querySelector('.workspace');workspace.append(inspector);const detail=workspace.querySelector('.center>.detail'),notes=workspace.querySelector('.center>.marking:not(#blockPanel)'),meter=workspace.querySelector('.instruments');if(detail)$('inspectorComponent').append(detail);if(notes)$('inspectorNotes').append(notes);if(meter)$('inspectorMeter').append(meter);
 function inspectTab(tab){for(const name of ['component','notes','meter'])$('inspector'+name[0].toUpperCase()+name.slice(1)).hidden=name!==tab;inspector.querySelectorAll('[data-inspector]').forEach(b=>b.setAttribute('aria-selected',String(b.dataset.inspector===tab)));}
 inspector.querySelectorAll('[data-inspector]').forEach(b=>b.onclick=()=>inspectTab(b.dataset.inspector));document.addEventListener('circuitlab:workspace',e=>inspectTab(e.detail==='diagnose'?'meter':'component'));document.addEventListener('circuitlab:component',()=>inspectTab('component'));
 let searchDialog=null;function openSearch(){if(searchDialog?.open){searchDialog.querySelector('input').focus();return;}searchDialog=document.createElement('dialog');searchDialog.className='platformSearch';searchDialog.innerHTML='<div class="searchHeading"><input type="search" placeholder="Placa, resistencia, alimentación, osciloscopio…" aria-label="Buscar lección, placa o circuito"><button aria-label="Cerrar búsqueda">×</button></div><p>Placas · Componentes · Lecciones · Circuitos</p><div class="platformSearchResults"></div>';document.body.append(searchDialog);const input=searchDialog.querySelector('input'),results=searchDialog.querySelector('.platformSearchResults');const render=()=>{results.innerHTML=searchLaboratory(api.boards,input.value).map(e=>`<button data-kind="${e.kind}" data-id="${esc(e.id)}"><span>${esc(e.label)}</span><div><b>${esc(e.title)}</b><small>${esc(e.detail)}</small></div><i>↗</i></button>`).join('')||'<p>Sin resultados. Prueba con una función o componente.</p>';results.querySelectorAll('button').forEach(b=>b.onclick=()=>{searchDialog.close();if(b.dataset.kind==='board')api.openBoard(b.dataset.id);else if(b.dataset.kind==='component'){const [board,ref]=b.dataset.id.split('::');api.openBoard(board);api.inspect(ref);}else if(b.dataset.kind==='lesson'){api.show('course');api.openLesson(b.dataset.id);}else{api.show('library');api.openCircuit(b.dataset.id);}});};input.oninput=render;input.onkeydown=e=>{if(e.key==='Enter')results.querySelector('button')?.click();};searchDialog.querySelector('.searchHeading button').onclick=()=>searchDialog.close();searchDialog.addEventListener('close',()=>searchDialog.remove(),{once:true});render();searchDialog.showModal();input.focus();}
 $('globalSearch').onclick=openSearch;document.addEventListener('keydown',e=>{if((e.ctrlKey||e.metaKey)&&e.key.toLowerCase()==='k'){e.preventDefault();openSearch();}});
 $('backupOpen').onclick=()=>{const dialog=document.createElement('dialog');dialog.className='platformBackup';dialog.innerHTML='<button class="backupClose" aria-label="Cerrar">×</button><span class="studioEyebrow">CONTINUIDAD ENTRE DISPOSITIVOS</span><h2>Todo tu progreso, en un archivo.</h2><p>Incluye el curso, los proyectos, cuadernos, marcas y ajustes guardados en este navegador. Descarga la copia antes de cambiar de dominio o dispositivo.</p><button id="backupDownload" class="academyPrimary">Descargar copia completa</button><label class="projectImport">Restaurar copia<input id="backupFile" type="file" accept=".json,application/json"></label><p>Al restaurar se sustituyen las claves incluidas en la copia. Descarga primero una copia del estado actual si quieres conservarlo.</p><p id="backupStatus" role="status"></p>';document.body.append(dialog);dialog.querySelector('.backupClose').onclick=()=>dialog.close();dialog.addEventListener('close',()=>dialog.remove(),{once:true});dialog.showModal();$('backupDownload').onclick=()=>{const data=makeBackup(api.storage),url=URL.createObjectURL(new Blob([JSON.stringify(data)],{type:'application/json'})),a=document.createElement('a');a.href=url;a.download='circuitlab-copia-'+new Date().toISOString().slice(0,10)+'.json';a.click();setTimeout(()=>URL.revokeObjectURL(url),1000);$('backupStatus').textContent=Object.keys(data.values).length+' elementos exportados.';};$('backupFile').onchange=async e=>{const f=e.target.files[0];if(!f)return;try{if(f.size>10e6)throw Error('La copia supera 10 MB.');const count=restoreBackup(api.storage,JSON.parse(await f.text()));$('backupStatus').textContent=count+' elementos restaurados. Recarga para aplicarlos.';const reload=document.createElement('button');reload.textContent='Recargar aplicación';reload.onclick=()=>location.reload();$('backupStatus').append(reload);}catch(error){$('backupStatus').textContent=error.message;}};};
 document.querySelector('.studioVersion').textContent='NEXT';document.querySelector('.studioHero .studioEyebrow').textContent='TU LABORATORIO · CIRCUITLAB';return {openSearch,inspectTab};
}
